  INSERT INTO bantrly.lesson_content (content_id, lesson_id, content_key, content_value, created_at, updated_at) VALUES
    (gen_random_uuid(), v_lesson_id, 'topic', 'Making a quick decision is sometimes better than waiting until you have all the information.', NOW(), NOW())
,    (gen_random_uuid(), v_lesson_id, 'user_side', 'Waiting for More Information', NOW(), NOW())
,    (gen_random_uuid(), v_lesson_id, 'ai_side', 'Quick Decision', NOW(), NOW())
,    (gen_random_uuid(), v_lesson_id, 'content', 'Making a timely decision keeps things moving, and sometimes the cost of waiting is higher than the risk of being slightly wrong.
That makes sense. Why might someone argue that rushing into a decision almost always leads to bigger mistakes?
Final thought.', NOW(), NOW())
